mapper.select:
SELECT a.shop_id, a.shop_name, a.osAmount + IFNULL( roc.notSettlementMoney, 0 ) AS osAmount, a.osOrderReturnAmount, a.osRedpacketAmount, a.osRedpacketReturnAmount, IFNULL( b.withdrawalAmount, 0 ) AS withdrawalAmount, c.undrawnAmount, IFNULL( roc.notSettlementMoney, 0 ) AS notSettlementMoney FROM ( SELECT shop_id, shop_name, sum( os_order_amount ) AS osAmount, sum( os_order_return_amount ) AS osOrderReturnAmount, sum( os_redpacket_amount ) AS osRedpacketAmount, sum( os_redpacket_return_amount ) AS osRedpacketReturnAmount FROM ${database.prefix.order}hou_order_settlement WHERE os_datetime BETWEEN #{param.startTime} and #{param.endTime} GROUP BY shop_id ) a left join (select shop_id,sum(os_amount) as withdrawalAmount FROM ${database.prefix.order}hou_order_settlement where os_state = 5 and os_datetime BETWEEN #{param.startTime} and #{param.endTime} GROUP BY shop_id ) b on a.shop_id = b.shop_id LEFT JOIN (select shop_id,sum(os_amount) as undrawnAmount FROM ${database.prefix.order}hou_order_settlement where os_state in (1,4) and os_datetime BETWEEN #{param.startTime} and #{param.endTime} GROUP BY shop_id ) c on a.shop_id = c.shop_id left join (SELECT oa.orderAmount - IFNULL(ro.returnAmount,0) as notSettlementMoney,oa.shop_id FROM (SELECT ( sum( order_payment_amount ) + sum( order_rpt_price ) ) AS orderAmount, shop_id,shop_name FROM ${database.prefix.order}hou_order_base WHERE order_is_settlement = '0' and order_status BETWEEN 2 and 6 and payment_time BETWEEN #{param.startTime} AND #{param.endTime} GROUP BY shop_id ) oa LEFT JOIN ( SELECT (sum( return_cash ) + sum( return_rpt_cash ) )AS returnAmount,shop_id,shop_name from ${database.prefix.order}hou_order_return WHERE order_is_settlement = '0' AND return_state = '4' and return_add_time BETWEEN #{param.startTime} AND #{param.endTime}
GROUP BY shop_id ) ro ON oa.shop_id = ro.shop_id ) roc ON a.shop_id = roc.shop_id
and a.shop_name like concat('%',#{param.shopName},'%')

SELECT os.os_id, os.os_start_date, os.os_end_date, os.os_order_amount, os.os_shipping_amount, os.os_order_return_amount, os.os_commis_amount, os.os_commis_return_amount, os.os_shop_cost_amount, os.os_platform_bear_amount, os.os_platform_bear_return_amount, os.os_amount, os.os_datetime, os.os_date, os.os_state, os.os_pay_date, os.os_pay_content, os.shop_id, os.shop_name, os.os_order_type, os.os_redpacket_amount, os.os_redpacket_return_amount, os.district_id, os.os_dealer_commission, os.os_dealer_return_commission, os.os_supply_commission, os.os_supply_return_commission, os.os_base_member_discount, os.os_return_member_discount, os.os_tg_commission, os.os_fx_commission, os.os_supper_discount_fee, os.os_return_supper_discount_fee, os.os_supply_price, os.os_return_supply_price -- , -- oog.goods_id, -- oog.goods_name, -- oog.order_goods_payment_amount FROM ${database.prefix.order}hou_order_settlement os -- left join ${database.prefix.order}hou_order_base oob on (oob.order_settlement_id = os.os_id -- or oob.order_supply_settlement_id = os.os_id) -- left join ${database.prefix.order}hou_order_goods oog on oob.order_id = oog.order_id where os.shop_id = #{paraMap.shopId} and os.os_is_display = 1
and os.os_id = #{paraMap.osId}
and os.os_state =#{paraMap.osState}
AND os.os_order_type = #{paraMap.osOrderType}
order by os.os_datetime desc

SELECT os.os_id, os.os_start_date, os.os_end_date, os.os_order_amount, os.os_shipping_amount, os.os_order_return_amount, os.os_commis_amount, os.os_commis_return_amount, os.os_shop_cost_amount, os.os_platform_bear_amount, os.os_platform_bear_return_amount, os.os_amount, os.os_datetime, os.os_date, os.os_state, os.os_pay_date, os.os_pay_content, os.shop_id, os.shop_name, os.os_order_type, os.os_redpacket_amount, os.os_redpacket_return_amount, os.district_id, os.os_dealer_commission, os.os_dealer_return_commission, os.os_supply_commission, os.os_supply_return_commission, os.os_base_member_discount, os.os_return_member_discount, os.os_tg_commission, os.os_fx_commission, os.os_supper_discount_fee, os.os_return_supper_discount_fee, os.os_supply_price, os.os_return_supply_price -- , -- oog.goods_id, -- oog.goods_name, -- oog.order_goods_payment_amount FROM ${database.prefix.order}hou_order_settlement os -- left join ${database.prefix.order}hou_order_base oob on (oob.order_settlement_id = os.os_id -- or oob.order_supply_settlement_id = os.os_id) -- left join ${database.prefix.order}hou_order_goods oog on oob.order_id = oog.order_id where os.shop_id = #{paraMap.shopId} and os.os_is_display = 1
and os.os_id = #{paraMap.osId}
and os.os_state =#{paraMap.osState}
AND os.os_order_type = #{paraMap.osOrderType}
order by os.os_datetime desc

select os_date, os_start_date, os_end_date, os_datetime, shop_id, os_order_type
FROM ${database.prefix.order}hou_order_settlement
where os_id = #{paraMap.orderSettlementId}

SELECT ob.order_id ,( if(oog.drop_shipping = 1,sob.goods_payment_amount - ob.order_shipping_fee,ob.order_payment_amount) ) AS orderPaymentAmount, ob.order_shipping_fee , ( if(oog.drop_shipping = 1,sob.supper_commission,ob.order_commission_fee) ) AS order_commission_fee , ob.order_create_time , ob.order_finished_time , ob.buyer_user_id , ob.buyer_user_name , ob.base_member_discount , ob.distribution_discount as orderDiscountFee, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount FROM ${database.prefix.order}hou_order_base ob left join ${database.prefix.order}hou_order_goods oog on ob.order_id = oog.order_id LEFT join ${database.prefix.order}hou_order_commission oc ON ob.order_id = oc.order_id LEFT join ${database.prefix.order}hou_order_supplier_base sob on sob.order_id = ob.order_id WHERE ob.order_status IN ( '6', '9' ) and order_supply_is_settlement = 1
and ob.order_finished_time >= #{paraMap.osStartDate}
and ob.order_finished_time <= #{paraMap.osEndDate}
and (ob.shop_id = #{paraMap.shopId} or oog.deliver_shop_id = #{paraMap.shopId})
and ob.order_supply_settlement_id = #{paraMap.orderSettlementId}
and ob.order_supply_settlement_time like concat('%',#{paraMap.osDatetime},'%')
group by ob.order_id,oog.goods_id order by ob.order_finished_time desc

SELECT ob.order_id ,( if(oog.drop_shipping = 1,sob.goods_payment_amount - oog.shipping_fee,oog.order_goods_payment_amount) ) AS orderPaymentAmount, oog.shipping_fee as orderShippingFee, ( if(oog.drop_shipping = 1,sob.supper_commission,oog.order_goods_commission) ) AS order_commission_fee , ob.order_create_time , ob.order_finished_time , ob.buyer_user_id , ob.buyer_user_name , oog.goods_member_discount as baseMemberDiscount, ob.distribution_discount as orderDiscountFee, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount FROM ${database.prefix.order}hou_order_base ob left join ${database.prefix.order}hou_order_goods oog on ob.order_id = oog.order_id LEFT join ${database.prefix.order}hou_order_commission oc ON ob.order_id = oc.order_id LEFT join ${database.prefix.order}hou_order_supplier_base sob on sob.order_id = ob.order_id WHERE ob.order_status IN ( '6', '9' ) and order_supply_is_settlement = 1
and ob.order_finished_time >= #{paraMap.osStartDate}
and ob.order_finished_time <= #{paraMap.osEndDate}
and (ob.shop_id = #{paraMap.shopId} or oog.deliver_shop_id = #{paraMap.shopId})
and ob.order_supply_settlement_id = #{paraMap.orderSettlementId}
and ob.order_supply_settlement_time like concat('%',#{paraMap.osDatetime},'%')
group by ob.order_id,oog.goods_id order by ob.order_finished_time desc

select b.order_id,b.order_payment_amount,b.order_rpt_price,b.order_shipping_fee,c.commission_money as order_commission_fee, b.order_create_time, b.order_finished_time,b.buyer_user_id,b.buyer_user_name, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount FROM ${database.prefix.order}hou_order_base b left join ${database.prefix.order}hou_order_goods oog on b.order_id = oog.order_id left join ${database.prefix.order}hou_order_commission c on b.order_id = c.order_id where b.order_status = 6
and b.order_live_settlement_id = = #{paraMap.orderSettlementId}
group by b.order_id,oog.goods_id order by b.order_finished_time desc

SELECT ob.order_id, ob.order_payment_amount - ob.order_shipping_fee as order_payment_amount, ob.order_supply_amount, ob.order_rpt_price, ob.order_shipping_fee, ob.order_commission_fee, ob.order_create_time, ob.order_finished_time, ob.buyer_user_id, ob.buyer_user_name, ob.base_member_discount, oc.one_tg_commission + two_tg_commission as tg_commission , oc.fx_commission, sob.goods_price_sum, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount FROM ${database.prefix.order}hou_order_base ob left join ${database.prefix.order}hou_order_goods oog on ob.order_id = oog.order_id LEFT join ${database.prefix.order}hou_order_commission oc ON ob.order_id = oc.order_id LEFT join ${database.prefix.order}hou_order_supplier_base sob on sob.order_id = ob.order_id WHERE ( ob.order_status IN ('6', '9') or (ob.virtual_goods = 0 and is_cancel= 2)) and ob.order_is_settlement = 1 and oog.drop_shipping =1 and ob.payment_code <> 3
and ob.order_finished_time >= #{paraMap.osStartDate}
and ob.order_finished_time <= #{paraMap.osEndDate}
and ob.shop_id = #{paraMap.shopId}
and ob.order_settlement_id = #{paraMap.orderSettlementId}
and ob.order_settlement_time like concat('%',#{paraMap.osDatetime},'%')
group by ob.order_id,oog.goods_id order by ob.order_finished_time desc

SELECT ob.order_id, oog.order_goods_payment_amount as order_payment_amount, sob.goods_price as order_supply_amount, oog.order_rpt_price, oog.shipping_fee as order_shipping_fee, oog.order_goods_commission as order_commission_fee, ob.order_create_time, ob.order_finished_time, ob.buyer_user_id, ob.buyer_user_name, oog.goods_member_discount as base_member_discount, oc.one_tg_commission + two_tg_commission as tg_commission , oc.fx_commission, sob.goods_price_sum, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount FROM ${database.prefix.order}hou_order_base ob left join ${database.prefix.order}hou_order_goods oog on ob.order_id = oog.order_id LEFT join ${database.prefix.order}hou_order_commission oc ON ob.order_id = oc.order_id LEFT join ${database.prefix.order}hou_order_supplier_base sob on sob.order_id = ob.order_id WHERE ( ob.order_status IN ('6', '9') or (ob.virtual_goods = 0 and is_cancel= 2)) and ob.order_is_settlement = 1 and oog.drop_shipping =1 and ob.payment_code <> 3 and ob.shop_id != oog.deliver_shop_id
and ob.order_finished_time >= #{paraMap.osStartDate}
and ob.order_finished_time <= #{paraMap.osEndDate}
and ob.shop_id = #{paraMap.shopId}
and ob.order_settlement_id = #{paraMap.orderSettlementId}
and ob.order_settlement_time like concat('%',#{paraMap.osDatetime},'%')
group by ob.order_id,oog.goods_id order by ob.order_finished_time desc

SELECT ob.order_id, ob.order_payment_amount - ob.order_shipping_fee-ob.end_free as order_payment_amount, ob.order_supply_amount, ob.order_rpt_price, ob.order_shipping_fee, ob.order_commission_fee, ob.order_create_time, ob.order_finished_time, ob.buyer_user_id, ob.buyer_user_name, ob.base_member_discount, oc.one_tg_commission + two_tg_commission as tg_commission , oc.fx_commission, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount FROM ${database.prefix.order}hou_order_base ob left join ${database.prefix.order}hou_order_goods oog on ob.order_id = oog.order_id LEFT join ${database.prefix.order}hou_order_commission oc on ob.order_id = oc.order_id WHERE ( ob.order_status IN ('6', '9') or (ob.virtual_goods = 0 and is_cancel= 2)) and ob.order_is_settlement = 1 and ob.payment_code != 3
and ob.order_finished_time >= #{paraMap.osStartDate}
and ob.order_finished_time <= #{paraMap.osEndDate}
and ob.shop_id = #{paraMap.shopId}
and ob.order_settlement_id = #{paraMap.orderSettlementId}
and ob.order_settlement_time like concat('%',#{paraMap.osDatetime},'%')
group by ob.order_id,oog.goods_id order by ob.order_finished_time desc

SELECT ob.order_id, ob.order_payment_amount, ob.order_supply_amount, ob.order_rpt_price, ob.order_shipping_fee, ob.order_commission_fee, ob.order_create_time, ob.order_finished_time, ob.buyer_user_id, ob.buyer_user_name, ob.base_member_discount, oc.one_tg_commission + two_tg_commission as tg_commission , oc.fx_commission, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount FROM ${database.prefix.order}hou_order_base ob left join ${database.prefix.order}hou_order_goods oog on ob.order_id = oog.order_id LEFT join ${database.prefix.order}hou_order_commission oc on ob.order_id = oc.order_id WHERE ( ob.order_status IN ('6', '9') or (ob.virtual_goods = 0 and is_cancel= 2)) and ob.order_is_settlement = 1 and ob.payment_code != 3
and ob.order_finished_time >= #{paraMap.osStartDate}
and ob.order_finished_time <= #{paraMap.osEndDate}
and ob.shop_id = #{paraMap.shopId}
and ob.order_settlement_id = #{paraMap.orderSettlementId}
and ob.order_settlement_time like concat('%',#{paraMap.osDatetime},'%')
group by ob.order_id order by ob.order_finished_time desc

SELECT oor.return_code , oor.order_id, if(oog.drop_shipping = 1,if(oor.return_method_status = 1,sob.order_refund_price,sob.order_return_price), oor.return_cash) AS return_cash, if(oog.drop_shipping = 1,sob.supper_return_commission,oor.return_commision_fee) AS return_commision_fee , oor.return_state , oor.return_add_time, oor.return_finish_time, oor.buyer_user_account , oor.return_rpt_cash , oor.return_reason, oor.return_member_discount , oor.return_supper_discount_fee, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount, oog.order_goods_amount FROM ${database.prefix.order}hou_order_return oor LEFT join ${database.prefix.order}hou_order_base oob ON oor.order_id = oob.order_id left join ${database.prefix.order}hou_order_goods oog on oog.order_id = oob.order_id LEFT join ${database.prefix.order}hou_order_supplier_base sob on sob.order_id = oor.order_id WHERE oor.order_supply_is_settlement = 1 AND oor.return_state IN ( 2,4 )
and oor.return_finish_time >= #{paraMap.osStartDate}
and oor.return_finish_time <= #{paraMap.osEndDate}
and (oob.shop_id = #{paraMap.shopId} or oog.deliver_shop_id = #{paraMap.shopId})
and oor.order_supply_settlement_id = #{paraMap.orderSettlementId}
group by oob.order_id,oog.goods_id order by oor.return_add_time desc

SELECT oor.return_code, oor.order_id, oor.return_cash, oor.return_rpt_cash, oor.return_commision_fee, oor.return_state, oor.return_add_time, oor.return_finish_time, oor.buyer_user_account, oor.shop_name, oor.return_member_discount, sob.order_return_price, oor.return_reason, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount, oog.order_goods_amount FROM ${database.prefix.order}hou_order_return oor LEFT join ${database.prefix.order}hou_order_base oob ON oor.order_id = oob.order_id left join ${database.prefix.order}hou_order_goods oog on oog.order_id = oob.order_id LEFT join ${database.prefix.order}hou_order_supplier_base sob on sob.order_id = oob.order_id WHERE 1=1 and oor.order_is_settlement ='1' AND oog.drop_shipping = 1
and oor.return_finish_time >= #{paraMap.osStartDate}
and oor.return_finish_time <= #{paraMap.osEndDate}
and oor.shop_id = #{paraMap.shopId}
and oor.order_settlement_id = #{paraMap.orderSettlementId}
group by oob.order_id,oog.goods_id order by oor.return_add_time desc

SELECT oor.return_code, oor.order_id, oor.return_cash, oor.return_rpt_cash, oor.return_commision_fee, oor.return_state, oor.return_add_time, oor.return_finish_time, oor.buyer_user_account, oor.shop_name, oor.return_reason, date_format( oor.return_finish_time, '%Y-%m-%d %H:%i:%s' ) AS returnFinishTime, oor.return_member_discount, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount, oog.order_goods_amount FROM ${database.prefix.order}hou_order_return oor left join ${database.prefix.order}hou_order_goods oog on oog.order_id = oor.order_id WHERE 1=1
and oor.return_finish_time >= #{paraMap.osStartDate}
and oor.return_finish_time <= #{paraMap.osEndDate}
and oor.shop_id = #{paraMap.shopId}
and oor.order_settlement_id = #{paraMap.orderSettlementId}
and oor.order_settlement_time like CONCAT('%',#{paraMap.osDatetime},'%')
and oor.return_shop_handle in (0,2,4,5)
group by oor.order_id ,oog.goods_id order by oor.return_finish_time desc

SELECT oor.return_code, oor.order_id, oor.return_cash, oor.return_rpt_cash, oor.return_commision_fee, oor.return_state, oor.return_add_time, oor.buyer_user_account, oor.shop_name, oor.return_reason, date_format( oor.return_finish_time, '%Y-%m-%d %H:%i:%s' ) AS returnFinishTime, oor.return_member_discount, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount FROM ${database.prefix.order}hou_order_return oor left join ${database.prefix.order}hou_order_goods oog on oog.order_id = oor.order_id WHERE oog.drop_shipping = 2
and oor.return_finish_time >= #{paraMap.osStartDate}
and oor.return_finish_time <= #{paraMap.osEndDate}
and oor.shop_id = #{paraMap.shopId}
and oor.order_settlement_id = #{paraMap.orderSettlementId}
and oor.order_settlement_time like CONCAT('%',#{paraMap.osDatetime},'%')
and oor.return_shop_handle in (0,2,4,5)
group by oor.order_id order by oor.return_finish_time desc

SELECT ob.order_id, ( oog.order_goods_payment_amount - oog.shipping_fee ) AS order_payment_amount, ( if(oog.drop_shipping = 1,sob.goods_price_sum,oog.order_goods_amount)) AS order_supply_amount, oog.order_rpt_price, oog.shipping_fee, if(oog.drop_shipping = 1,sob.supper_commission,oog.order_goods_commission) AS order_commission_fee, ob.order_create_time, ob.order_finished_time, ob.buyer_user_id, ob.buyer_user_name, ob.distribution_discount as orderDiscountFee, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount FROM ${database.prefix.order}hou_order_base ob left join ${database.prefix.order}hou_order_goods oog on oog.order_id = ob.order_id LEFT join ${database.prefix.order}hou_order_commission oc ON ob.order_id = oc.order_id LEFT join ${database.prefix.order}hou_order_supplier_base sob on sob.order_id = ob.order_id and oog.deliver_shop_id = sob.supplier_shop_id LEFT JOIN ${database.prefix.goods}hou_goods_base gb on oog.goods_id = gb.goods_id WHERE ob.order_status IN ( '6', '9' ) and order_supply_is_settlement = 1 AND gb.supplier_goods_id = sob.goods_id
and ob.order_finished_time >= #{paraMap.osStartDate}
and ob.order_finished_time < #{paraMap.osEndDate}
and (ob.shop_id = #{paraMap.shopId} or oog.deliver_shop_id = #{paraMap.shopId})
and ob.order_supply_settlement_id = #{paraMap.orderSettlementId}
group by ob.order_id,oog.goods_id order by ob.order_finished_time desc

SELECT ob.order_id, ob.order_payment_amount, ob.order_supply_amount, ob.order_rpt_price, ob.order_shipping_fee, ob.order_commission_fee, ob.order_create_time, ob.order_finished_time, ob.buyer_user_id, ob.buyer_user_name, ob.base_member_discount, oc.one_tg_commission + two_tg_commission as tg_commission, oc.fx_commission FROM ${database.prefix.order}hou_order_base ob LEFT join ${database.prefix.order}hou_order_commission oc ON ob.order_id = oc.order_id WHERE ( ob.order_status IN ( '6', '9' ) OR ( ob.virtual_goods = 0 AND is_cancel = 2 ) ) AND ob.order_is_settlement = 1 and ob.payment_code != 3
and ob.order_finished_time >= #{paraMap.osStartDate}
and ob.order_finished_time < #{paraMap.osEndDate}
and ob.shop_id = #{paraMap.shopId}
and ob.order_settlement_id = #{paraMap.orderSettlementId}
and ob.order_settlement_time like concat('%',#{paraMap.osDatetime},'%')
group by ob.order_id order by ob.order_finished_time desc

SELECT oor.return_code, oor.order_id, if(oog.drop_shipping = 1,if(oor.return_method_status = 1,sob.order_refund_price,sob.order_return_price), oor.return_cash) AS return_cash, ( if(oog.drop_shipping = 1,sob.goods_price_sum,oog.order_goods_amount)) AS order_supply_amount, if(oog.drop_shipping = 1,sob.supper_return_commission,oor.return_commision_fee) AS return_commision_fee, oor.return_state, oor.return_add_time, oor.buyer_user_account, oor.order_id, oor.shop_name, date_format( oor.return_finish_time, '%Y-%m-%d %H:%i:%s' ) AS return_finish_time, oor.return_rpt_cash , oor.return_reason, oor.return_supper_discount_fee, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount FROM ${database.prefix.order}hou_order_return oor LEFT join ${database.prefix.order}hou_order_base oob ON oor.order_id = oob.order_id left join ${database.prefix.order}hou_order_goods oog on oog.order_id = oob.order_id LEFT join ${database.prefix.order}hou_order_supplier_base sob on sob.order_id = oor.order_id and oog.deliver_shop_id = sob.supplier_shop_id LEFT JOIN ${database.prefix.goods}hou_goods_base gb on oog.goods_id = gb.goods_id where 1=1 AND oor.order_supply_is_settlement = 1 AND oor.return_state IN ( 2,4 ) AND (oog.goods_return_status = 2 or oog.goods_refund_status = 2) AND gb.supplier_goods_id = sob.goods_id
and oor.return_finish_time >= #{paraMap.osStartDate}
and oor.return_finish_time <= #{paraMap.osEndDate}
and (oob.shop_id = #{paraMap.shopId} or oog.deliver_shop_id = #{paraMap.shopId})
and oor.order_supply_settlement_id = #{paraMap.orderSettlementId}
group by oob.order_id,oog.goods_id order by oor.return_finish_time desc

SELECT oor.return_code, oor.order_id, oor.return_cash, oor.return_commision_fee, oor.return_state, oor.return_add_time, oor.buyer_user_account, oor.shop_name, oor.return_reason, date_format( oor.return_finish_time, '%Y-%m-%d %H:%i:%s' ) AS return_finish_time, oor.return_member_discount, oog.goods_id, oog.goods_name, oog.order_goods_payment_amount FROM ${database.prefix.order}hou_order_return oor left join ${database.prefix.order}hou_order_goods oog on oog.order_id = oor.order_id where 1=1
and oor.return_shop_handle in (0,2,4,5)
and oor.return_finish_time >= #{paraMap.osStartDate}
and oor.return_finish_time <= #{paraMap.osEndDate}
and oor.shop_id = #{paraMap.shopId}
and oor.order_settlement_id =#{paraMap.orderSettlementId}
and oor.order_settlement_time like CONCAT('%',#{paraMap.osDatetime},'%')
group by oor.order_id,oog.goods_id order by oor.return_finish_time desc

select os_date FROM ${database.prefix.order}hou_order_settlement
where shop_id = #{shopId}

    and os_order_type = #{osOrderType}

order by os_datetime desc limit 1

SELECT sum( ob.order_shipping_fee ) AS orderShippingFee, sum( ob.order_payment_amount ) AS orderPaymentAmount, sum( ob.order_rpt_price ) AS orderRptPrice, sum( ob.base_member_discount ) AS baseMemberDiscount FROM ${database.prefix.order}hou_order_base ob WHERE ob.shop_id = #{param.shopId} AND ob.order_is_settlement ='0' AND ob.original_order IS NULL AND ob.payment_code != 3 AND ob.pay_code != 13 AND (( ob.order_status IN ( '6', '9' ) AND ob.virtual_goods = 1 ) OR ( ob.order_status = '9' AND ob.virtual_goods = 1 AND ob.order_refund_status = 2 ) OR ( ob.virtual_goods = 0 AND ob.is_cancel = 0 AND ob.order_status IN ( '6' ) ) OR ( ob.virtual_goods = 0 AND ob.is_cancel = 2 AND ob.order_status IN ( '9', '12' ) ) )
and ob.order_finished_time >= #{param.dBefore} and ob.order_finished_time <= now()
and ob.order_finished_time >= #{param.start} and ob.order_finished_time <= #{param.end}

SELECT ob.order_id FROM ${database.prefix.order}hou_order_base ob WHERE ob.shop_id = #{param.shopId} AND ob.order_is_settlement ='0' AND ob.original_order IS NULL AND ob.payment_code != 3 AND ob.pay_code != 13 AND (( ob.order_status IN ( '6', '9' ) AND ob.virtual_goods = 1 ) OR ( ob.order_status = '9' AND ob.virtual_goods = 1 AND ob.order_refund_status = 2 ) OR ( ob.virtual_goods = 0 AND ob.is_cancel = 0 AND ob.order_status IN ( '6' ) ) OR ( ob.virtual_goods = 0 AND ob.is_cancel = 2 AND ob.order_status IN ( '9', '12' ) ) )
and ob.order_finished_time >= #{param.dBefore} and ob.order_finished_time <= now()
and ob.order_finished_time >= #{param.start} and ob.order_finished_time <= #{param.end}

select sum(IFNULL(oor.return_rpt_cash,0)) as returnRptCash, sum(IFNULL(oor.return_member_discount,0)) AS returnMemberDiscount, sum(IFNULL(oc.return_one_tg_commission,0)+IFNULL(oc.return_two_tg_commission,0)) AS returnTgCommission, sum(IFNULL(oc.return_fx_commission,0)) AS returnFxCommission, SUM(IFNULL(oor.return_cash,0)) as selfSellingReturnCash, SUM(IFNULL(oor.return_commision_fee,0)) as selfSellingReturnCommission FROM ${database.prefix.order}hou_order_return oor LEFT join ${database.prefix.order}hou_order_base oob on oor.order_id = oob.order_id LEFT join ${database.prefix.order}hou_order_commission oc on oob.order_id = oc.order_id and oc.order_status = 4 where oor.shop_id = #{param.shopId} and oob.original_order is null and oor.order_is_settlement = '0' and oob.payment_code != 3 and oob.pay_code != 13 and ((oor.return_state = 2 and oor.return_method_status in (1, 2)) or (oor.return_state = 4 and oor.return_method_status = 3) or (oob.virtual_goods = 0 and oob.is_cancel = 2))
and oor.return_finish_time >= #{param.dBefore} and oor.return_finish_time <= now()
and oor.return_finish_time >= #{param.start} and oor.return_finish_time <= #{param.end}

SELECT IFNULL( SUM( og.goods_return_price ), 0 ) AS selfSellingReturnCash, IFNULL( SUM( og.dealer_return_commission), 0 ) AS selfSellingReturnCommission FROM ${database.prefix.order}hou_order_return oor LEFT join ${database.prefix.order}hou_order_base oob ON oor.order_id = oob.order_id LEFT join ${database.prefix.order}hou_order_goods og ON og.order_id = oob.order_id WHERE oob.original_order IS NULL AND oor.shop_id = #{param.shopId} AND og.drop_shipping = 1 AND og.order_goods_returnnum > 0 AND (og.goods_return_status = 2 OR og.goods_refund_status = 2) AND oob.pay_code != 13 AND oob.payment_code != 3 AND ( oor.return_type IN ( 1, 2 ) OR ( oob.virtual_goods = 0 AND oob.is_cancel = 2 ) ) AND oor.order_is_settlement = '0' AND oor.return_state IN ( 2, 4 )
and oor.return_finish_time >= #{param.dBefore} and oor.return_finish_time <= now()
and oor.return_finish_time >= #{param.start} and oor.return_finish_time <= #{param.end}

SELECT IFNULL( SUM( og.goods_return_price ), 0 ) AS sellOnReturnCash, IFNULL( SUM( og.dealer_return_commission ), 0 ) AS sellOnReturnCommission FROM ${database.prefix.order}hou_order_return AS oor LEFT join ${database.prefix.order}hou_order_base oob ON oor.order_id = oob.order_id LEFT join ${database.prefix.order}hou_order_goods og ON og.order_id = oob.order_id WHERE oob.original_order is null and oor.shop_id = #{param.shopId} AND og.drop_shipping = 1 AND og.order_goods_returnnum > 0 AND (og.goods_return_status = 2 OR og.goods_refund_status = 2) and oob.pay_code != 13 and oob.payment_code != 3 and (oor.return_type in (1, 2) or (oob.virtual_goods = 0 and oob.is_cancel = 2)) and oor.order_is_settlement = '0' and oor.return_state in (2, 4)
and oor.return_finish_time >= #{param.dBefore} and oor.return_finish_time <= now()
and oor.return_finish_time >= #{param.start} and oor.return_finish_time <= #{param.end}

select SUM(oor.return_cash) FROM ${database.prefix.order}hou_order_return AS oor LEFT join ${database.prefix.order}hou_order_base oob on oor.order_id = oob.order_id where oob.original_order is not null and oor.shop_id = #{param.shopId} and oob.pay_code != 13 and oob.payment_code != 3 and (oor.return_type in (1, 2) or (oob.virtual_goods = 0 and oob.is_cancel = 2)) and oor.order_is_settlement = '0' and oor.return_state in (2, 4)
and oor.return_finish_time >= #{param.dBefore} and oor.return_finish_time <= now()
