select oob.order_id FROM ${database.prefix.order}hou_order_return oor LEFT join ${database.prefix.order}hou_order_base oob on oor.order_id = oob.order_id LEFT join ${database.prefix.order}hou_order_commission oc on oob.order_id = oc.order_id and oc.order_status = 4 where oor.shop_id = #{param.shopId} and oob.original_order is null and oor.order_is_settlement = '0' and oob.payment_code != 3 and oob.pay_code != 13 and ((oor.return_state = 2 and oor.return_method_status in (1, 2)) or (oor.return_state = 4 and oor.return_method_status = 3) or (oob.virtual_goods = 0 and oob.is_cancel = 2))
and oor.return_finish_time >= #{param.dBefore} and oor.return_finish_time <= now()
