SELECT os.os_id, os.os_start_date, os.os_end_date, os.os_order_amount, os.os_shipping_amount, os.os_order_return_amount, os.os_commis_amount, os.os_shop_cost_amount, os.os_commis_return_amount, os.os_platform_bear_amount, os.os_platform_bear_return_amount, os.os_amount, os.os_datetime, os.os_date, os.os_state, os.os_pay_date, os.os_pay_content, os.shop_id, sb.shop_name, os.os_order_type, os.os_redpacket_amount, os.os_redpacket_return_amount, os.district_id, os.os_base_member_discount, os.os_return_member_discount, os.os_tg_commission, os.os_fx_commission, os.os_supper_discount_fee, os.os_return_supper_discount_fee, os.os_supply_price, os.os_return_supply_price, sb.shop_settlement_cycle FROM ${database.prefix.order}hou_order_settlement os left join ${database.prefix.supplier}hou_shop_base sb on sb.supplier_shop_id = os.shop_id WHERE os.os_is_display = 1
and os.os_id = #{refundMap.osId}
