and os_datetime >= #{refundMap.osStartDate}
and os_datetime <= #{refundMap.osFinishTime}
order by os.os_datetime desc

SELECT os_id, os_start_date, os_end_date, os_order_amount, os_shipping_amount, os_order_return_amount, os_commis_amount, os_shop_cost_amount, os_commis_return_amount, os_platform_bear_amount, os_platform_bear_return_amount, os_amount, os_datetime, os_date, os_state, os_pay_date, os_pay_content, shop_id, shop_name, os_order_type, os_redpacket_amount, os_redpacket_return_amount, district_id, os_base_member_discount, os_return_member_discount, os_tg_commission, os_fx_commission, os_supper_discount_fee, os_return_supper_discount_fee, os_supply_price, os_return_supply_price FROM ${database.prefix.order}hou_order_settlement WHERE os_is_display = 1
and os_id = #{refundMap.osId}
